// Widget state/event tests with a tiny in-memory DOM (not a visual browser test).
'use strict';const test=require('node:test'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),path=require('node:path'),catalog=require('../src/catalog.js');
function setup(opts={}){class N{constructor(tag){this.tag=tag;this.child=[];this.listeners={};this.className='';this._text='';this.isConnected=true;this.validity={valid:true};this.value='';}set textContent(v){this._text=String(v);this.child=[];}get textContent(){return this._text+this.child.map(n=>n.textContent).join('');}append(...kids){for(let x of kids){if(typeof x==='string'){const n=new N('#text');n.textContent=x;x=n;}x.parent=this;this.child.push(x);}}replaceChildren(){this.child=[];}attachShadow(){return this.shadow=new N('root');}setAttribute(k,v){this['@'+k]=v;}addEventListener(k,fn){(this.listeners[k]||=[]).push(fn);}click(){(this.listeners.click||[]).forEach(fn=>fn({currentTarget:this}));}focus(){}remove(){if(this.parent)this.parent.child=this.parent.child.filter(x=>x!==this);this.isConnected=false;}*walk(){for(const n of this.child){yield n;yield* n.walk();}}querySelectorAll(q){return [...this.walk()].filter(n=>q.startsWith('.')?n.className.split(' ').includes(q.slice(1)):n.tag===q);}getBoundingClientRect(){return {top:0};}}
const doc={body:new N('body'),createElement:t=>new N(t)};const ctx=vm.createContext({document:doc,AbortController,URL,setTimeout,clearTimeout,requestAnimationFrame:f=>f(),location:{href:'https://site.test/',origin:'https://site.test'},fetch:opts.fetch});const files=['src/engine.js','src/theme.js','src/widget.js'];files.forEach(f=>vm.runInContext(fs.readFileSync(path.join(__dirname,'..',f),'utf8'),ctx));let selected;const w=ctx.BangbomChat.mount({catalog,includeSamples:true,startOpen:true,onFloorplan:x=>{selected=x;},...opts});const root=doc.body.child[0].shadow;return {w,root,click(t,where=root){const b=where.querySelectorAll('button').find(x=>x.textContent===t);assert.ok(b,'button: '+t);b.click();},cards:()=>root.querySelectorAll('.card'),selected:()=>selected};}
test('위젯: 자유 입력 → 확인 → 추천 → 비교 → 평면도 단지 ID',()=>{const t=setup();t.w.open('달서구 2억 5천 이하, 넓은 집');assert.equal(t.w.getProfile().district,null);t.click('이대로 반영');assert.equal(t.cards().length,3);assert.match(t.cards()[0].textContent,/상인푸르지오/);t.click('앞의 두 곳 비교');assert.match(t.root.querySelectorAll('.sheet')[0].textContent,/1,200만/);t.click('닫기',t.root.querySelectorAll('.sheet')[0]);t.click('평면도 보기');assert.equal(t.selected().id,'sangin-centerpark');});
test('위젯: 수성구 예산 미충족 → 허용 후에만 완화',()=>{const t=setup();t.click('수성구');t.click('2억 이하');t.click('보증금 낮은 순');assert.equal(t.cards().length,0);t.click('상한을 3억 2,000만 원으로 변경');assert.equal(t.cards().length,1);assert.equal(t.w.getProfile().maxDeposit,32000);});
test('위젯: 주어진 조건 재질문 생략 + 후보 간 차이',()=>{const t=setup({initialProfile:{district:'달서구',maxDeposit:25000}});assert.match(t.root.textContent,/마음이 가세요/);t.click('면적 넓은 순');assert.equal(t.cards().length,3);});
test('위젯: 단순 가족 언급으로 타겟 추론하지 않고 가구 도구는 명시 동의 후 연결',()=>{const t=setup();t.w.open('아이랑 살 집');assert.equal(t.cards().length,0);assert.ok(!t.root.textContent.includes('확인 항목에 추가'));t.w.open('가구 배치 해보고 싶어요');t.click('확인 항목에 추가');t.click('지금 후보 보기');t.click('가구 배치 확인');assert.equal(t.selected().viewIntent,'furniture');});
test('위젯: AI는 동의 전 미호출, 응답은 승인 후 적용',async()=>{let calls=0,body;const t=setup({interpretEndpoint:'/api/prefs',fetch:async(u,o)=>{calls++;body=JSON.parse(o.body);return {ok:true,json:async()=>({patch:{maxDeposit:25000},unsupported:false})};}});t.w.open('이억 오천 이하');assert.equal(calls,0);t.click('이 문장만 AI로 해석');await new Promise(r=>setImmediate(r));assert.equal(calls,1);assert.equal(body.text,'이억 오천 이하');assert.deepEqual(Object.keys(body).sort(),['step','text']);assert.equal(t.w.getProfile().maxDeposit,null);t.click('이대로 반영');assert.equal(t.w.getProfile().maxDeposit,25000);});
test('위젯: AI 장애 → 로컬 제안 복구',async()=>{const t=setup({interpretEndpoint:'/api/prefs',fetch:async()=>{throw Error('offline');}});t.w.open('2억 이하');t.click('이 문장만 AI로 해석');await new Promise(r=>setImmediate(r));assert.match(t.root.textContent,/기본 해석으로 읽었어요/);t.click('이대로 반영');assert.equal(t.w.getProfile().maxDeposit,20000);});
test('위젯: AI 응답 중 새 대화 → 늦게 도착한 결과 무시',async()=>{let finish;const t=setup({interpretEndpoint:'/api/prefs',fetch:()=>new Promise(r=>{finish=r;})});t.w.open('이억 이하');t.click('이 문장만 AI로 해석');t.click('새 대화');t.click('대화 지우고 시작');finish({ok:true,json:async()=>({unsupported:false,patch:{maxDeposit:20000}})});await new Promise(r=>setImmediate(r));assert.equal(t.w.getProfile().maxDeposit,null);assert.ok(!t.root.textContent.includes('AI가 읽은 조건'));});
